import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"出站代理（Mux、XUDP）","description":"","frontmatter":{},"headers":[],"relativePath":"config/outbound.md","filePath":"config/outbound.md","lastUpdated":1789080411000}`),a={name:`config/outbound.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /config/outbound.md for this page in Markdown format</div><h1 id="出站代理-mux、xudp" tabindex="-1">出站代理（Mux、XUDP） <a class="header-anchor" href="#出站代理-mux、xudp" aria-label="Permalink to “出站代理（Mux、XUDP）”">​</a></h1><p>出站连接用于发送数据，可用的协议请见 <a href="./outbounds/">出站协议</a>。</p><h2 id="outboundobject" tabindex="-1">OutboundObject <a class="header-anchor" href="#outboundobject" aria-label="Permalink to “OutboundObject”">​</a></h2><p><code>OutboundObject</code> 对应配置文件中 <code>outbounds</code> 项的一个子元素。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>列表中的第一个元素作为主 outbound。当路由匹配不存在或没有匹配成功时，流量由主 outbound 发出。</p></div><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;outbounds&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: [</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">    {</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;sendThrough&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;0.0.0.0&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;protocol&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;协议名称&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;settings&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {},</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;tag&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;标识&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;streamSettings&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {},</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;mux&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {},</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;targetStrategy&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;AsIs&quot;</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">    }</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">  ]</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><blockquote><p><code>sendThrough</code>: address</p></blockquote><p>用于发送数据的 IP 地址，当主机有多个 IP 地址时有效，默认值为 <code>&quot;0.0.0.0&quot;</code>。</p><p>允许在其中填入 IPv6 CIDR 块 (如 114:514:1919:810::/64)，Xray 将会使用地址块中随机的 IP 地址对外发起连接。 需要正确配置网络接入方式，路由表以及内核参数以允许 Xray bind 至地址块内的任意 IP。</p><p>对于使用 ndp 接入的网络，不建议设置小于 /120 的子网，否则可能会造成 NDP flood 导致路由器邻居缓存被占满等一系列问题。</p><p>特殊值 <code>origin</code> 若使用该值，将使用本机被连接的 IP 发出请求。</p><p>特殊值 <code>srcip</code> 若使用该值，将使用入站时的源 IP 发出请求。</p><p>例如机器上存在一整段 IPv4 <code>11.4.5.0/24</code> 且监听 0.0.0.0 (网卡上的全部 IPv4 与 IPv6)，若客户端通过 <code>11.4.5.14</code> 连接到本机，那么出站也会通过 <code>11.4.5.14</code> 发送对外请求；如果使用 <code>11.4.5.10</code> 连接到本机，那么出站就会通过 <code>11.4.5.10</code> 发送请求。 同样适用于机器上有整段/复数个 IPv6 的情况。</p><p>和入站介绍的一样，因为 UDP 的无连接特性 Xray 无从得知这个请求进入核心的原目标 IP (举个例子，在同一个 QUIC 连接里它甚至可能变动)，所以这个功能无法生效。</p><blockquote><p><code>protocol</code>: &quot;blackhole&quot; | &quot;dns&quot; | &quot;freedom&quot; | &quot;http&quot; | &quot;loopback&quot; | &quot;shadowsocks&quot; | &quot;socks&quot; | &quot;trojan&quot; | &quot;vless&quot; | &quot;vmess&quot; | &quot;hysteria&quot; | &quot;wireguard&quot;</p></blockquote><p>连接协议名称，可选的协议列表见左侧 <a href="./outbounds/">出站协议</a>。</p><blockquote><p><code>settings</code>: OutboundConfigurationObject</p></blockquote><p>具体的配置内容，视协议不同而不同。详见每个协议中的 <code>OutboundConfigurationObject</code>。</p><blockquote><p><code>tag</code>: string</p></blockquote><p>此出站连接的标识，用于在其它的配置中定位此连接。</p><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">DANGER</p><p>当其不为空时，其值必须在所有 <code>tag</code> 中 <strong>唯一</strong>。</p></div><blockquote><p><code>streamSettings</code>: <a href="./transport.html">StreamSettingsObject</a></p></blockquote><p>此出站的传输配置。</p><blockquote><p><code>mux</code>: <a href="#muxobject">MuxObject</a></p></blockquote><p>Mux 相关的具体配置。</p><blockquote><p><code>targetStrategy</code>: &quot;AsIs&quot; | &quot;UseIP&quot; | &quot;UseIPv6v4&quot; | &quot;UseIPv6&quot; | &quot;UseIPv4v6&quot; | &quot;UseIPv4&quot; | &quot;ForceIP&quot; | &quot;ForceIPv6v4&quot; | &quot;ForceIPv6&quot; | &quot;ForceIPv4v6&quot; | &quot;ForceIPv4&quot;</p></blockquote><p>适用于 Freedom 以外的出站，控制被代理请求中的目标域名是否在本地解析为 IP，以及使用何种解析策略。</p><p>默认值为 <code>AsIs</code>，即保持目标域名原样发送到远端服务器。各策略的含义与 <a href="./transports/sockopt.html#sockoptobject">sockopt</a> 中的 <code>domainStrategy</code> 基本相同。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>这里控制的是<strong>被代理的请求</strong>，如果出站代理服务器的地址是域名，并需要为这个域名本身选择解析策略，则应配置 <a href="./transports/sockopt.html#sockoptobject">sockopt</a> 中的 <code>domainStrategy</code>。</p><p>Freedom 出站的域名解析策略也应配置 <code>sockopt.domainStrategy</code>。</p></div><h3 id="muxobject" tabindex="-1">MuxObject <a class="header-anchor" href="#muxobject" aria-label="Permalink to “MuxObject”">​</a></h3><p>Mux 功能是在一条 TCP 连接上分发多个 TCP 连接的数据。实现细节详见 <a href="./../development/protocols/muxcool.html">Mux.Cool</a>。Mux 是为了减少 TCP 的握手延迟而设计，而非提高连接的吞吐量。使用 Mux 看视频、下载或者测速通常都有反效果。Mux 只需要在客户端启用，服务器端自动适配。Mux 的第二个用途是分发多个 UDP 连接，即 XUDP。</p><p><code>MuxObject</code> 对应 <code>OutboundObject</code> 中的 <code>mux</code> 项。</p><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;enabled&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">true</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;concurrency&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">8</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;xudpConcurrency&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">16</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;xudpProxyUDP443&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;reject&quot;</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><blockquote><p><code>enabled</code>: true | false</p></blockquote><p>是否启用 Mux 转发请求，默认值 <code>false</code>。</p><blockquote><p><code>concurrency</code>: number</p></blockquote><p>最大并发连接数。最小值 <code>1</code>，最大值 <code>128</code>。省略或者填 <code>0</code> 时都等于 <code>8</code>, 大于 <code>128</code> 的值都将视为 128, 因为当一个连接达到最大复用次数 128 后其将不会再被分配任何新的子连接。</p><p>这个数值表示了一个 TCP 连接上最多承载的子连接数量。比如设置 <code>concurrency=8</code> 时，当客户端发出了 8 个 TCP 请求，Xray 只会发出一条实际的 TCP 连接，客户端的 8 个请求全部由这个 TCP 连接传输。</p><p>当全部 Mux 连接的最大子连接连接都已被占满，核心将发出新的连接承载子连接。如果短时间内并发大量子连接后续逐渐减少，核心内部调度器将倾向于将请求分配至 2 个连接交替使用并闲置其他连接等待它们的所有子连接自然结束后将其关闭以节约资源。如果总子连接数继续长时间低于 <code>concurrency</code> 则在其中一条达到最大复用次数后核心将回到单连接状态。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>填负数时，如 <code>-1</code>，不使用 Mux 模块承载 TCP 流量。</p></div><blockquote><p><code>xudpConcurrency</code>: number</p></blockquote><p>使用新 XUDP 聚合隧道（也就是另一条 Mux 连接）代理 UDP 流量，填写最大并发子 UoT 数量。最小值 <code>1</code>，最大值 <code>1024</code>。 省略或者填 <code>0</code> 时，将与 TCP 流量走同一条路，也就是传统的行为。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>填负数时，如 <code>-1</code>，不使用 Mux 模块承载 UDP 流量。将使用代理协议原本的 UDP 传输方式。例如 <code>Shadowsocks</code> 会使用原生 UDP，<code>VLESS</code> 会使用 UoT。</p></div><blockquote><p><code>xudpProxyUDP443</code>: string</p></blockquote><p>控制 Mux 对于被代理的 UDP/443（QUIC）流量的处理方式：</p><ul><li>默认 <code>reject</code> 拒绝流量（一般浏览器会自动回落到 TCP HTTP2）</li><li><code>allow</code> 允许走 Mux 连接。</li><li>填 <code>skip</code> 时，不使用 Mux 模块承载 UDP 443 流量。将使用代理协议原本的 UDP 传输方式。例如 <code>Shadowsocks</code> 会使用原生 UDP，<code>VLESS</code> 会使用 UoT。</li></ul>`,47)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};